<script setup lang="ts">
import { Head, Link, useForm } from '@inertiajs/vue3'; import ErpLayout from '@/Layouts/ErpLayout.vue'; import type { BranchOption, TreasuryAccountOption } from '@/Types/treasury'; defineOptions({layout:ErpLayout}); const props=defineProps<{branches:BranchOption[];bankAccounts:TreasuryAccountOption[];currencyCode:string}>(); const form=useForm<{branch_id:number|null;bank_account_id:number|null;statement_reference:string;period_start:string;period_end:string;currency_code:string;opening_balance:string;closing_balance:string;statement_file:File|null}>({branch_id:null,bank_account_id:null,statement_reference:'',period_start:'',period_end:'',currency_code:props.currencyCode,opening_balance:'0.000000',closing_balance:'',statement_file:null}); const setFile=(event:Event):void=>{const input=event.target as HTMLInputElement;form.statement_file=input.files?.[0]??null;}; const submit=():void=>form.post(route('bank-statements.store'),{forceFormData:true});
</script>
<template><Head title="Import Bank Statement"/><form class="space-y-6" @submit.prevent="submit"><div><Link :href="route('bank-statements.index')" class="text-sm text-brand-600">Bank Statements</Link><h1 class="mt-2 text-2xl font-semibold">Import Bank Statement</h1><p class="mt-1 text-sm text-gray-500">Upload the standard CSV template. Maximum 10,000 rows.</p></div><div class="rounded-2xl border bg-white p-6 dark:border-gray-800 dark:bg-gray-900"><div class="mb-5 flex justify-end"><a :href="route('bank-statements.template')" class="text-sm font-medium text-brand-600">Download CSV template</a></div><div class="grid gap-5 md:grid-cols-2 xl:grid-cols-3"><label class="space-y-1 text-sm">Branch<select v-model="form.branch_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select><span class="text-xs text-error-500">{{form.errors.branch_id}}</span></label><label class="space-y-1 text-sm">Bank Account<select v-model="form.bank_account_id" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"><option :value="null">Select</option><option v-for="a in bankAccounts" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><span class="text-xs text-error-500">{{form.errors.bank_account_id}}</span></label><label class="space-y-1 text-sm">Statement Reference<input v-model="form.statement_reference" maxlength="160" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/><span class="text-xs text-error-500">{{form.errors.statement_reference}}</span></label><label class="space-y-1 text-sm">Period Start<input v-model="form.period_start" type="date" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Period End<input v-model="form.period_end" :min="form.period_start" type="date" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Currency<input v-model="form.currency_code" readonly class="h-11 w-full rounded-lg border bg-gray-50 px-3 dark:border-gray-700 dark:bg-gray-800"/></label><label class="space-y-1 text-sm">Opening Balance<input v-model="form.opening_balance" type="number" step="0.000001" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm">Closing Balance<input v-model="form.closing_balance" type="number" step="0.000001" class="h-11 w-full rounded-lg border px-3 dark:border-gray-700"/></label><label class="space-y-1 text-sm md:col-span-2 xl:col-span-3">CSV Statement<input type="file" accept=".csv,text/csv" class="block w-full rounded-lg border p-3 dark:border-gray-700" @change="setFile"/><span class="text-xs text-error-500">{{form.errors.statement_file}}</span></label></div></div><div class="flex justify-end gap-3"><Link :href="route('bank-statements.index')" class="rounded-lg border px-5 py-2.5 text-sm dark:border-gray-700">Cancel</Link><button :disabled="form.processing" class="rounded-lg bg-brand-500 px-5 py-2.5 text-sm text-white disabled:opacity-50">{{form.processing?'Importing...':'Import Statement'}}</button></div></form></template>
